!function(t){function i(i){for(var r,e,m=i[0],o=i[1],p=i[2],c=0,g=[];c<m.length;c++)e=m[c],Object.prototype.hasOwnProperty.call(n,e)&&n[e]&&g.push(n[e][0]),n[e]=0;for(r in o)Object.prototype.hasOwnProperty.call(o,r)&&(t[r]=o[r]);for(u&&u(i);g.length;)g.shift()();return s.push.apply(s,p||[]),a()}function a(){for(var t,i=0;i<s.length;i++){for(var a,e=s[i],m=!0,o=1;o<e.length;o++)a=e[o],0!==n[a]&&(m=!1);m&&(s.splice(i--,1),t=r(r.s=e[0]))}return t}function r(i){if(e[i])return e[i].exports;var a=e[i]={i:i,l:!1,exports:{}};return t[i].call(a.exports,a,a.exports,r),a.l=!0,a.exports}var e={},n={21:0},s=[];r.m=t,r.c=e,r.d=function(t,i,a){r.o(t,i)||Object.defineProperty(t,i,{enumerable:!0,get:a})},r.r=function(t){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(t,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(t,"__esModule",{value:!0})},r.t=function(t,i){if(1&i&&(t=r(t)),8&i)return t;if(4&i&&"object"==typeof t&&t&&t.__esModule)return t;var a=Object.create(null);if(r.r(a),Object.defineProperty(a,"default",{enumerable:!0,value:t}),2&i&&"string"!=typeof t)for(var e in t)r.d(a,e,function(i){return t[i]}.bind(null,e));return a},r.n=function(t){var i=t&&t.__esModule?function(){return t.default}:function(){return t};return r.d(i,"a",i),i},r.o=function(t,i){return Object.prototype.hasOwnProperty.call(t,i)},r.p="";var m=window.webpackJsonp=window.webpackJsonp||[],o=m.push.bind(m);m.push=i,m=m.slice();for(var p=0;p<m.length;p++)i(m[p]);var u=o;s.push([19,0]),a()}({19:function(t,i,a){"use strict";a.r(i);var r=a(0);Object(r.a)("us","army",a(20),a(1))},20:function(t){t.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"坦克","link":"us_army#us_army_tank"}],"model":"M5轻型坦克","description":"<h6>综述：</h6><p>M5是M3轻型坦克的后续车型，也是一种轻型坦克，也称“斯图亚特Ⅵ型”，由于M5是从M3发展而来，且性能相近，一些资料则将这两种型号统一称为“M3/M5，斯图亚特”。M5系列坦克有“M5”和“M5A1”二种型号，其中M5轻型坦克在1942年3月开始生产，但M5轻型坦克未曾正式装备给美军部队，后经过标准化改造与性能提升，定型为M5A1，1943年，M5A1正式装备美军，并援助给英国等盟军部队，由于M5A1轻型坦克具有灵活与较好的机动性，因此被英军大量接收；但苏军则认为M5与M3性能并无多大差别，而M3又无法对抗德军坦克，因此拒绝了接受M5。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"{{text}}1942年11月，卡萨布兰卡，美军第70独立坦克营的M5轻型坦克。{{image}}imgs/us/army/us_army_tankm5_11.jpg{{text}}1944年7月，在意大利蒙坦约内的美军第1装甲师第81侦察营的M5轻型坦克。{{image}}imgs/us/army/us_army_tankm5_12.jpg","description":"<h6>M5轻型坦克</h6><p>M5轻型坦克采用了M3A3的炮塔，武器配备与M3A3基本相同，但装甲加厚了，车体大量采用了焊接构件，通过将坦克底盘降低，增大发动机功率，使坦克的可靠性与行程都有所增大。</p><p>坦克参数（供参考）为：</p><p>车长: 4.33M, 车宽：2.24m, 车高：2.30m, 车重：14.73t； 装甲厚度：12-67mm；发动机功率：320匹马力，车速：58km/h, 最大行程：160km。武器装备：1门37mm火炮和3挺机枪。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>炮塔（圆形）、悬挂系统（4个负重轮）与M3A3相同。</li><li>车体前装甲有倾角，后部结构作了抬高（M3A3是平直的）。</li><li>高射机枪置放于炮塔后顶部。</li></ol></span>","caption":""},{"image":"{{text}}1944年，在英国，美军第4装甲师第25骑兵侦察大队一辆命名“Rocket(火箭）”的M5A1轻型坦克。{{image}}imgs/us/army/us_army_tankm5_21.jpg{{text}}1945年1-2月间，在法国的Colmar地区，美军第12装甲师第92骑兵侦察大队的一辆M5A1轻型坦克。{{image}}imgs/us/army/us_army_tankm5_22.jpg","description":"<h6>M5A1轻型坦克</h6><p>M5A1轻型坦克是在M5基础上改进的，其与M5不同处是炮塔增大了，舱口也扩大了，设置了为无线电台专用的炮塔尾部突出舱，并在炮塔两侧加装了装甲防护裙板，整车防护得到了加强。</p><p>从1943年初开始，M5A1替代了M5，当年就生产了2000多辆，到1944年，一共生产了6810辆，其中有1431辆在在英国服役（1943-1944年间）。</p><p>M5A1除车重比M5重了约2t外，其它参数两者基本相同。</p><span class=\'custom-document-caption text-secondary\'><strong>外形特点：</strong><ol><li>炮塔加大了，有突出的尾舱。</li><li>炮塔两侧加装了装甲裙板。</li><li>高射机枪置放于炮塔顶中。</li><li>在炮塔顶后部有电台天线。</li></ol></span>","caption":""}],"part2title":"战场上的M5轻型坦克","part2description":"<p>M5A1轻型坦克最早出现在突尼斯和西西里战役，除了美军大量配备外，英军也大量装备准备作反攻用，在欧洲与亚洲战场上，到处都可见到它的身影。但M5A1坦克除了具备灵活、高机动性的优点外，其装甲和火力已远远落后，在欧洲战场，不但德军坦克炮，反坦克炮是它的杀手，连铁拳步兵反坦克火箭弹都难以抵挡，生存率极低；在西欧和北欧战场，美军一共损失了770多辆M5A1坦克，在意大利战场也损失了400多辆，可见战损之严重。1945年，美军第2装甲师给盟军总司令艾森豪威尔的报告中说：M5轻型坦克无论从哪个方面来说都不适合作为战斗坦克使用，这种坦克应交付给步兵部队。</p>","part2content":[{"image":"imgs/us/army/us_army_tankm5_31.jpg","description":"1944年1月22日，在Anzio地区，从一辆两栖登陆舰登岸的美军第751坦克营D连的一队M5A1轻型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm5_32.jpg","description":"1944年10月20日，支援美军第1骑兵师在菲律宾Leyte岛上作战的美国陆军第44坦克营的一辆M5A1轻型坦克正在穿越丛林。","caption":""},{"image":"imgs/us/army/us_army_tankm5_33.jpg","description":"1944年2月1日，在太平洋岛屿登陆战中，美国海军陆战队第4坦克营的一辆M5轻型坦克正在支援海军陆战队战士向敌方阵地进攻，该坦克采用了第4坦克营的常用涂装。","caption":""},{"image":"imgs/us/army/us_army_tankm5_34.jpg","description":"1944年11月29日，在意大利Capua地区，一辆正在执行任务的美军M5A1轻型坦克不慎陷入淤泥中，其车组成员正想法脱离困境。该坦克车体是经过伪装涂彩的。","caption":""},{"image":"imgs/us/army/us_army_tankm5_35.jpg","description":"1944年11月16日，在德国贝根多夫地区，在突破西格弗里德防线作战中，美军第2装甲师第67装甲团B连的一辆M5A1坦克正在行进，该坦克车身前有加固了的沙袋和原木作加强防御用，这辆坦克属于1943年生产型，其机枪安装方式与后期型不同，采用的是T36E7伯吉斯-诺顿钢支架。","caption":""},{"image":"imgs/us/army/us_army_tankm5_36.jpg","description":"1945年3月2日，在德国的Viersen镇，美军第5装甲师第34坦克营D连的一辆M5A1坦克上，车长在正用坦克上装备的高射机枪向远处一个隐藏的敌军目标开火。图中持机枪的车长头戴的是法式坦克成员头盔。","caption":""},{"image":"imgs/us/army/us_army_tankm5_37.jpg","description":"1945年3月7日，在德国Bad Godesberg镇郊区外围，两辆隶属美军746坦克营的M5A1轻型坦克经过一个被摧毁的工厂。它们正在支援美军第9步兵师的战斗，该师当天正试图夺取这个城镇，配合美军第9装甲师沿着莱茵河进攻。","caption":""},{"image":"imgs/us/army/us_army_tankm5_38.jpg","description":"1945年4月10日，在德国的Peine镇，一辆安装了扩音器的美军第5装甲师的M5A1轻型坦克。","caption":""},{"image":"imgs/us/army/us_army_tankm5_39.jpg","description":"1945年7月28日，支援美军第12装甲师的第116骑兵侦察大队的一辆M5A1轻型坦克正在通过德国Heim镇。","caption":""},{"image":"imgs/us/army/us_army_tankm5_40.jpg","description":"隶属美军第3装甲师33装甲团的一辆M5A1坦克正在德国Airel小镇的一处密布弹痕的建筑旁边经过，有一个洋娃娃不知是谁放在残留的废墟上。在这里，美军抗击了德军第9步兵师的多次攻击。","caption":""},{"image":"imgs/us/army/us_army_tankm5_41.jpg","description":"一名美军宪兵正在指挥第3装甲师第33装甲团的M5A1坦克通过德国一个小镇。","caption":""},{"image":"imgs/us/army/us_army_tankm5_42.jpg","description":"一辆美军的M5A1轻型坦克下在战斗行进中。","caption":""},{"image":"imgs/us/army/us_army_tankm5_43.jpg","description":"一辆M5A1轻型坦克的车组成员正在察看损坏的悬挂系统。该坦克前装甲有一个黑豹徽标，可能是隶属一个美军坦克歼击营的侦察连。","caption":""},{"image":"imgs/us/army/us_army_tankm5_44.jpg","description":"美军一辆M5轻型坦克，车体前部白圈中的数字是该坦克桥梁承受力的标志。","caption":""}]}')}});